// De-serialize the instance of [aastypes.ISomething]
// as a sequence of XML elements, each representing a property
// of [aastypes.ISomething].
//
// The reading stops as soon as we encounter a non-start element, and we return
// that token as the `next` token.
func readSomethingAsSequence(
	decoder *xml.Decoder,
	current xml.Token,
) (instance aastypes.ISomething,
	next xml.Token,
	err error,
) {
	var theStructuralProperty *aastypes.StructuralUnion
	var theMixedProperty *aastypes.MixedUnion
	var theModelTypedProperty *aastypes.ModelTypedUnion
	var theListStructuralProperty []*aastypes.StructuralUnion
	var theListMixedProperty []*aastypes.MixedUnion
	var theListModelTypedProperty []*aastypes.ModelTypedUnion
	var theTupleProperty aascommon.Tuple3[*aastypes.StructuralUnion, *aastypes.MixedUnion, *aastypes.ModelTypedUnion]
	var theOptionalStructuralProperty *aastypes.StructuralUnion
	var theOptionalMixedProperty *aastypes.MixedUnion
	var theOptionalModelTypedProperty *aastypes.ModelTypedUnion

	foundStructuralProperty := false
	foundMixedProperty := false
	foundModelTypedProperty := false
	foundListStructuralProperty := false
	foundListMixedProperty := false
	foundListModelTypedProperty := false
	foundTupleProperty := false
	foundOptionalStructuralProperty := false
	foundOptionalMixedProperty := false
	foundOptionalModelTypedProperty := false

	for {
		var local string
		var ok bool
		local, current, ok, err = nextProperty(decoder, current, "ISomething")
		if err != nil {
			return
		}
		if !ok {
			break
		}

		var valueErr error
		switch local {
		case "structuralProperty":
			if foundStructuralProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theStructuralProperty, current, valueErr = xmlcommon.ReadElementDispatched(
				decoder, current, readStructuralUnionDispatched,
			)
			foundStructuralProperty = true
		case "mixedProperty":
			if foundMixedProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theMixedProperty, current, valueErr = xmlcommon.ReadElementDispatched(
				decoder, current, readMixedUnionDispatched,
			)
			foundMixedProperty = true
		case "modelTypedProperty":
			if foundModelTypedProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theModelTypedProperty, current, valueErr = xmlcommon.ReadElementDispatched(
				decoder, current, readModelTypedUnionDispatched,
			)
			foundModelTypedProperty = true
		case "listStructuralProperty":
			if foundListStructuralProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theListStructuralProperty, current, valueErr = readListOf(
				decoder, current, readStructuralUnionDispatched,
			)
			foundListStructuralProperty = true
		case "listMixedProperty":
			if foundListMixedProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theListMixedProperty, current, valueErr = readListOf(
				decoder, current, readMixedUnionDispatched,
			)
			foundListMixedProperty = true
		case "listModelTypedProperty":
			if foundListModelTypedProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theListModelTypedProperty, current, valueErr = readListOf(
				decoder, current, readModelTypedUnionDispatched,
			)
			foundListModelTypedProperty = true
		case "tupleProperty":
			if foundTupleProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theTupleProperty, current, valueErr = readTuple3(
				decoder, current,
				readStructuralUnionDispatched,
				readMixedUnionDispatched,
				readModelTypedUnionDispatched,
			)
			foundTupleProperty = true
		case "optionalStructuralProperty":
			if foundOptionalStructuralProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theOptionalStructuralProperty, current, valueErr = xmlcommon.ReadElementDispatched(
				decoder, current, readStructuralUnionDispatched,
			)
			foundOptionalStructuralProperty = true
		case "optionalMixedProperty":
			if foundOptionalMixedProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theOptionalMixedProperty, current, valueErr = xmlcommon.ReadElementDispatched(
				decoder, current, readMixedUnionDispatched,
			)
			foundOptionalMixedProperty = true
		case "optionalModelTypedProperty":
			if foundOptionalModelTypedProperty {
				valueErr = duplicatePropertyError(local)
				break
			}
			theOptionalModelTypedProperty, current, valueErr = xmlcommon.ReadElementDispatched(
				decoder, current, readModelTypedUnionDispatched,
			)
			foundOptionalModelTypedProperty = true
		default:
			valueErr = xmlcommon.NewDeserializationError(
				"Unexpected property",
			)
		}

		current, err = concludeProperty(decoder, current, local, valueErr)
		if err != nil {
			return
		}
	}

	next = current

	if !foundStructuralProperty {
		err = missingProperty("structuralProperty")
		return
	}

	if !foundMixedProperty {
		err = missingProperty("mixedProperty")
		return
	}

	if !foundModelTypedProperty {
		err = missingProperty("modelTypedProperty")
		return
	}

	if !foundListStructuralProperty {
		err = missingProperty("listStructuralProperty")
		return
	}

	if !foundListMixedProperty {
		err = missingProperty("listMixedProperty")
		return
	}

	if !foundListModelTypedProperty {
		err = missingProperty("listModelTypedProperty")
		return
	}

	if !foundTupleProperty {
		err = missingProperty("tupleProperty")
		return
	}

	instance = aastypes.NewSomething(
		theStructuralProperty,
		theMixedProperty,
		theModelTypedProperty,
		theListStructuralProperty,
		theListMixedProperty,
		theListModelTypedProperty,
		theTupleProperty,
	)
	instance.SetOptionalStructuralProperty(theOptionalStructuralProperty)
	instance.SetOptionalMixedProperty(theOptionalMixedProperty)
	instance.SetOptionalModelTypedProperty(theOptionalModelTypedProperty)
	return
}

// De-serialize an instance of [aastypes.IClass] based on the `local` name
// of its start element.
//
// The `current` token is expected to point to the content of that start element, and
// the resulting `next` token points to its end element.
func readClassDispatched(
	decoder *xml.Decoder,
	current xml.Token,
	local string,
) (instance aastypes.IClass,
	next xml.Token,
	err error,
) {
	switch local {
	case "structuralFirst":
		instance, next, err = readStructuralFirstAsSequence(decoder, current)
	case "structuralSecond":
		instance, next, err = readStructuralSecondAsSequence(decoder, current)
	case "mixedAbstractDescendantOne":
		instance, next, err = readMixedAbstractDescendantOneAsSequence(decoder, current)
	case "mixedAbstractDescendantTwo":
		instance, next, err = readMixedAbstractDescendantTwoAsSequence(decoder, current)
	case "mixedConcreteWithDescendants":
		instance, next, err = readMixedConcreteWithDescendantsAsSequence(decoder, current)
	case "mixedConcreteWithDescendantsChild":
		instance, next, err = readMixedConcreteWithDescendantsChildAsSequence(decoder, current)
	case "mixedConcreteLeaf":
		instance, next, err = readMixedConcreteLeafAsSequence(decoder, current)
	case "modelTypedFirst":
		instance, next, err = readModelTypedFirstAsSequence(decoder, current)
	case "modelTypedSecond":
		instance, next, err = readModelTypedSecondAsSequence(decoder, current)
	case "something":
		instance, next, err = readSomethingAsSequence(decoder, current)
	default:
		err = xmlcommon.NewDeserializationError(
			fmt.Sprintf(
				"Unexpected XML element name %s as class discriminator",
				local,
			),
		)
	}
	return
}

// Unmarshal an instance of [aastypes.IClass] serialized as an XML element.
//
// The XML element must live in the [Namespace] space.
func Unmarshal(
	decoder *xml.Decoder,
) (instance aastypes.IClass, err error) {
	var current xml.Token
	current, err = xmlcommon.ReadNext(decoder, nil)
	if err != nil {
		return
	}

	instance, _, err = xmlcommon.ReadElementDispatched(
		decoder, current, readClassDispatched,
	)
	return
}

// endregion

// region Serialization

// Represent an error during the serialization.
//
// Implements `error`.
type SerializationError = xmlcommon.SerializationError

// Write the optional `that` as an XML element with the `local` name, or write
// nothing at all if it is not set.
//
// Do not flush.
//
// A scalar and a tuple are not nilable in Golang, so an optional one is represented
// as a pointer. The pointer is dereferenced here, so that `writeContent` sees only
// the value. See also [writeOptionalInstance] and [writeOptionalSlice], which differ
// from this function only in how the presence is decided.
func writeOptionalPointer[T any](
	encoder *xml.Encoder,
	local string,
	that *T,
	writeContent func(anEncoder *xml.Encoder, aValue T) (anErr error),
) (err error) {
	if that == nil {
		return
	}

	return xmlcommon.WriteElement(encoder, local, *that, writeContent)
}

// Write the optional instance `that` as an XML element with the `local` name, or
// write nothing at all if it is not set.
//
// Do not flush.
//
// An instance is represented as an interface and a named union as a pointer to
// a struct, both of which are nil on their own, so -- unlike in [writeOptionalPointer] --
// there is no pointer to dereference.
//
// Golang does not allow a value of a type parameter to be compared against `nil`,
// and `any(that) == nil` would not do either: a nil *pointer* converted to `any` is
// a non-nil `any` which carries the type of that pointer. Comparing against
// the zero value of `T` covers both, as it compares nil against nil for
// an interface, and a nil pointer against a nil pointer of the same type for
// a named union.
func writeOptionalInstance[T any](
	encoder *xml.Encoder,
	local string,
	that T,
	writeContent func(anEncoder *xml.Encoder, aValue T) (anErr error),
) (err error) {
	var unset T
	if any(that) == any(unset) {
		return
	}

	return xmlcommon.WriteElement(encoder, local, that, writeContent)
}

// Write the optional `that` as an XML element with the `local` name, or write
// nothing at all if it is not set.
//
// Do not flush.
//
// A list and the bytes are represented as a slice, which is nil on its own, but --
// unlike an instance in [writeOptionalInstance] -- can not be compared against
// the zero value, as a slice is not comparable at all. Mind that a nil slice and
// an empty slice differ here: only the former is considered absent, while
// the latter is written as an empty XML element.
func writeOptionalSlice[T any](
	encoder *xml.Encoder,
	local string,
	that []T,
	writeContent func(anEncoder *xml.Encoder, aValue []T) (anErr error),
) (err error) {
	if that == nil {
		return
	}

	return xmlcommon.WriteElement(encoder, local, that, writeContent)
}

// Write the items of the `list`, each as an XML element of its own.
//
// Do not flush.
//
// The element *around* the list is framed by whoever writes the list, see
// the generated `writeListOf*` functions. Every item frames its own element
// through `writeItem`: an instance is written as an element named after its model
// type, while a scalar is wrapped in the element `v`. A list of instances and
// a list of scalars therefore share this one function.
func writeList[T any](
	encoder *xml.Encoder,
	list []T,
	writeItem func(anEncoder *xml.Encoder, aValue T) (anErr error),
) (err error) {
	for i, item := range list {
		err = writeItem(encoder, item)
		if err != nil {
			if seriaErr, ok := err.(*SerializationError); ok {
				seriaErr.Path.PrependIndex(
					&aasreporting.IndexSegment{Index: i},
				)
			}
			return
		}
	}

	return
}

// Conclude the writing of the property read by `getter` by attributing the error,
// if any, to that property.
//
// Do not flush.
//
// `getter` is the getter of the property *as it is spelled in Golang*, `Value()`
// and not `value`, since it is prepended to the path of a serialization error,
// which [SerializationError.PathString] renders as a Golang expression through
// [aasreporting.ToGolangPath]. (Golang has no way to name a member at compile time,
// so the getter has to be spelled out; mind that the de-serialization reports
// an XPath instead, and hence prepends the XML name there.)
//
// The write itself is given as its *result*, not as a function to be called, so that
// this one function concludes every property, no matter which of the `write*`
// functions wrote it, and no matter how many arguments that function took. Golang
// evaluates the argument, hence performs the write, before this call.
func finishProperty(
	getter string,
	err error,
) error {
	if err != nil {
		if seriaErr, ok := err.(*SerializationError); ok {
			seriaErr.Path.PrependName(
				&aasreporting.NameSegment{Name: getter},
			)
		}
		return err
	}

	return nil
}

// Write the instance `that` as an XML element named after its model type.
//
// Do not flush.
//
// This is the content writer of every instance which is not embedded in the element
// of its property, be it a property, a list item or a tuple item: [Marshal] picks
// the element name from the runtime model type.
//
// Golang function values are invariant in their parameter type, so [Marshal], which
// takes the wide [aastypes.IClass], can not be used where a writer of a more
// specific interface is expected -- this generic function exists solely to narrow
// the parameter type to `T`. Golang can not infer `T` from the context here, so
// every call site instantiates it explicitly, *e.g.*,
// `writeInstance[aastypes.IReference]`, and passes it on as that instantiated
// function value, without a closure.
func writeInstance[T aastypes.IClass](
	encoder *xml.Encoder,
	that T,
) error {
	return writeClass(encoder, that, false)
}

// Write `that` as an XML element with the `local` name representing its model type.
//
// Do not flush.
//
// If `withNamespace` is set, the `xmlns` attribute is set in the outer XML element.
//
// Unlike [xmlcommon.WriteElement], which frames a *property*, this function frames
// an instance in the element which discriminates its model type, and is therefore
// the one place where the XML namespace can be set.
func writeClassElement[T any](
	encoder *xml.Encoder,
	local string,
	withNamespace bool,
	that T,
	writeTAsSequence func(anEncoder *xml.Encoder, aValue T) (anErr error),
) (err error) {
	err = xmlcommon.WriteStartElement(encoder, local, withNamespace)
	if err != nil {
		return
	}

	err = writeTAsSequence(encoder, that)
	if err != nil {
		return
	}

	err = xmlcommon.WriteEndElement(encoder, local, withNamespace)
	return
}

// Constrain a generic type to a named union, giving access to its
// underlying instance for serialization.
type namedUnion interface {
	Underlying() aastypes.IClass
}

// Write the named union `that` as the XML element of its underlying instance.
//
// Do not flush.
//
// A named union is deliberately not an [aastypes.IClass], so [writeInstance] can not
// serve it; this writer narrows through the [namedUnion] constraint instead, and one
// generic writer thus covers every named union.
//
// Do not flush.
func writeUnion[T namedUnion](
	encoder *xml.Encoder,
	that T,
) error {
	return writeClass(encoder, that.Underlying(), false)
}

// Write `that` with `writeItem1`, `writeItem2`, *etc.* on the
// correspondingly positioned item, or return an error.
//
// Do not flush.
//
// Every item writes its own element, so this function is shared by every tuple of
// arity 3, whichever mix of scalar and instance items it holds.
func writeTuple3[T1 any, T2 any, T3 any](
	encoder *xml.Encoder,
	that aascommon.Tuple3[T1, T2, T3],
	writeItem1 func(encoder *xml.Encoder, value T1) error,
	writeItem2 func(encoder *xml.Encoder, value T2) error,
	writeItem3 func(encoder *xml.Encoder, value T3) error,
) (err error) {
	err = writeItem1(encoder, that.Item1)
	if err != nil {
		if seriaErr, ok := err.(*SerializationError); ok {
			seriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 0},
			)
		}
		return
	}

	err = writeItem2(encoder, that.Item2)
	if err != nil {
		if seriaErr, ok := err.(*SerializationError); ok {
			seriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 1},
			)
		}
		return
	}

	err = writeItem3(encoder, that.Item3)
	if err != nil {
		if seriaErr, ok := err.(*SerializationError); ok {
			seriaErr.Path.PrependIndex(
				&aasreporting.IndexSegment{Index: 2},
			)
		}
		return
	}

	return
}

